def parse_ini(text: str) -> dict[str, dict[str, str]]:
    sections: dict[str, dict[str, str]] = {}
    section_order: list[str] = []
    current_section: str | None = None
    prev_was_key = False
    prev_key: str | None = None

    for line in text.split('\n'):
        stripped = line.strip()

        # Rule 3: ignore empty lines and comment lines
        if stripped == '' or (len(stripped) > 0 and stripped[0] in ';#'):
            prev_was_key = False
            prev_key = None
            continue

        # Rule 1: section headers
        if stripped.startswith('[') and stripped.endswith(']'):
            section_name = stripped[1:-1].strip()
            current_section = section_name
            if section_name not in sections:
                sections[section_name] = {}
                section_order.append(section_name)
            prev_was_key = False
            prev_key = None
            continue

        # Rule 6: continuation lines
        if prev_was_key and len(line) > 0 and (line[0] == ' ' or line[0] == '\t'):
            if current_section is None:
                raise ValueError("Continuation line before any section")
            if prev_key is not None:
                sections[current_section][prev_key] += '\n' + stripped
            continue

        # Rule 2 & 10: key-value lines
        eq_pos = line.find('=')
        colon_pos = line.find(':')

        if eq_pos != -1 and colon_pos != -1:
            pos = min(eq_pos, colon_pos)
        elif eq_pos != -1:
            pos = eq_pos
        elif colon_pos != -1:
            pos = colon_pos
        else:
            raise ValueError(f"Malformed line: {line!r}")

        key = line[:pos].strip().lower()
        raw_value = line[pos + 1:]
        value = _process_value(raw_value)

        if current_section is None:
            raise ValueError("Key-value before any section")

        sections[current_section][key] = value
        prev_was_key = True
        prev_key = key

    # Resolve interpolation and build result
    result: dict[str, dict[str, str]] = {}
    for sec in section_order:
        if sec == 'DEFAULT':
            continue
        result[sec] = {}
        if 'DEFAULT' in sections:
            for dkey in sections['DEFAULT']:
                if dkey not in sections.get(sec, {}):
                    result[sec][dkey] = _resolve(sec, dkey, sections, set())
        if sec in sections:
            for key in sections[sec]:
                result[sec][key] = _resolve(sec, key, sections, set())

    return result


def _process_value(raw_value: str) -> str:
    stripped = raw_value.strip()
    if stripped.startswith('"'):
        end_quote = stripped.find('"', 1)
        if end_quote == -1:
            return stripped[1:]
        return stripped[1:end_quote]
    return _strip_comment(stripped)


def _strip_comment(value: str) -> str:
    in_quotes = False
    i = 0
    while i < len(value):
        if value[i] == '"':
            in_quotes = not in_quotes
        elif not in_quotes and value[i] in ';#':
            if i > 0 and value[i - 1] in ' \t':
                return value[:i - 1].rstrip()
        i += 1
    return value


def _resolve(section: str, key: str, sections: dict, visited: set) -> str:
    if (section, key) in visited:
        raise ValueError(f"Cycle detected: {section}:{key}")
    if section in sections and key in sections[section]:
        raw = sections[section][key]
    elif 'DEFAULT' in sections and key in sections['DEFAULT']:
        raw = sections['DEFAULT'][key]
    else:
        raise KeyError(f"Key {key!r} not found in section {section!r}")
    visited.add((section, key))
    result = _interpolate(raw, section, sections, visited)
    visited.discard((section, key))
    return result


def _interpolate(raw: str, current_section: str, sections: dict, visited: set) -> str:
    result = []
    i = 0
    while i < len(raw):
        if raw[i:i + 2] == '${':
            end = raw.find('}', i)
            if end == -1:
                result.append(raw[i:])
                break
            ref = raw[i + 2:end]
            if ':' in ref:
                sec, key = ref.split(':', 1)
                sec = sec.strip()
                key = key.strip().lower()
                if sec not in sections:
                    raise KeyError(f"Section {sec!r} not found")
            else:
                sec = current_section
                key = ref.strip().lower()
            value = _resolve(sec, key, sections, visited)
            result.append(value)
            i = end + 1
        else:
            result.append(raw[i])
            i += 1
    return ''.join(result)
