import re


def parse_duration(s: str) -> int:
    if not s or not s.strip():
        raise ValueError("Empty or blank string")

    pattern = re.compile(
        r"^\s*"
        r"(\d+)\s*([hmsHMS])"
        r"(?:\s*(\d+)\s*([hmsHMS]))?"
        r"(?:\s*(\d+)\s*([hmsHMS]))?"
        r"\s*$"
    )

    match = pattern.match(s)
    if not match:
        raise ValueError("Invalid duration string")

    parts: list[tuple[int, str]] = []
    for i in range(1, 7, 2):
        num = match.group(i)
        unit = match.group(i + 1)
        if num is not None:
            parts.append((int(num), unit.lower()))

    unit_priority = {"h": 0, "m": 1, "s": 2}
    seen: set[str] = set()
    prev_priority = -1
    for _num, unit in parts:
        if unit in seen:
            raise ValueError(f"Repeated unit: {unit}")
        seen.add(unit)
        if unit_priority[unit] < prev_priority:
            raise ValueError(f"Units out of order: {unit}")
        prev_priority = unit_priority[unit]

    total = 0
    for num, unit in parts:
        if unit == "h":
            total += num * 3600
        elif unit == "m":
            total += num * 60
        elif unit == "s":
            total += num

    return total
