def summarize_ranges(nums: list[int]) -> str:
    if not nums:
        return ""

    sorted_nums = sorted(set(nums))

    result = []
    start = sorted_nums[0]
    prev = sorted_nums[0]

    for num in sorted_nums[1:]:
        if num == prev + 1:
            prev = num
        else:
            if prev - start >= 2:
                result.append(f"{start}..{prev}")
            else:
                for i in range(start, prev + 1):
                    result.append(str(i))
            start = num
            prev = num

    if prev - start >= 2:
        result.append(f"{start}..{prev}")
    else:
        for i in range(start, prev + 1):
            result.append(str(i))

    return ",".join(result)
